import{f as e,j as t,m as n}from"./runtime-core.esm-bundler-DBPRRnSd.js";import{t as r}from"./plugin-vue_export-helper-CDQIAITX.js";var i=JSON.parse(`{"path":"/notes/%E9%9D%A2%E8%AF%95/java-%E5%B9%B6%E5%8F%91/","title":"Java并发 | notes","lang":"zh-CN","frontmatter":{"title":"Java并发","createTime":"2026/04/04 23:28:20","permalink":"/notes/面试/java-并发/","description":"[TOC] 线程同步 什么是 Java 中的线程同步？ - Java 并发面试题 - 面试鸭 - 程序员求职面试刷题神器 在多线程环境下，避免多个线程对共享资源进行同时访问，引发数据不一致或其它问题的机制。通过同一时刻只有一个线程能够访问共享资源 线程安全 Java 中的线程安全是什么意思？ - Java 并发面试题 - 面试鸭 - 程序员求职面试刷题...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Java并发\\",\\"image\\":[\\"https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250106163305676.png\\",\\"https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250106164353882.png\\",\\"https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250106164423270.png\\",\\"https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250106164449502.png\\",\\"https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250106164530788.png\\",\\"https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250107114105286.png\\",\\"https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250107115727555.png\\",\\"https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250107122402198.png\\"],\\"dateModified\\":\\"2026-06-25T07:15:35.000Z\\",\\"author\\":[]}"],["meta",{"property":"og:url","content":"http://xiaofei.site/notes/%E9%9D%A2%E8%AF%95/java-%E5%B9%B6%E5%8F%91/"}],["meta",{"property":"og:site_name","content":"计算机知识杂货铺"}],["meta",{"property":"og:title","content":"Java并发"}],["meta",{"property":"og:description","content":"[TOC] 线程同步 什么是 Java 中的线程同步？ - Java 并发面试题 - 面试鸭 - 程序员求职面试刷题神器 在多线程环境下，避免多个线程对共享资源进行同时访问，引发数据不一致或其它问题的机制。通过同一时刻只有一个线程能够访问共享资源 线程安全 Java 中的线程安全是什么意思？ - Java 并发面试题 - 面试鸭 - 程序员求职面试刷题..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250106163305676.png"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-06-25T07:15:35.000Z"}],["meta",{"property":"article:modified_time","content":"2026-06-25T07:15:35.000Z"}]]},"readingTime":{"minutes":6.21,"words":1862},"git":{"createdTime":1775331561000,"updatedTime":1782371735000,"contributors":[{"name":"xiaofei","username":"xiaofei","email":"tu_aofei@163.com","commits":1,"avatar":"https://avatars.githubusercontent.com/u/49927991?s=96&v=4","url":"https://github.com/731016"},{"name":"731016","username":"731016","email":"xiaofei00152@gmail.com","commits":1,"avatar":"https://avatars.githubusercontent.com/731016?v=4","url":"https://github.com/731016"}],"changelog":[{"hash":"6226c1c3cfce235348f612b9ec8a011caac82791","time":1782371735000,"email":"xiaofei00152@gmail.com","author":"731016","message":"更新侧边栏配置和图标"},{"hash":"fb8bc3afbb338138170b503192cbdb88a45075bd","time":1775331561000,"email":"tu_aofei@163.com","author":"xiaofei","message":"更新为vuepress"}]},"autoDesc":true,"filePathRelative":"notes/面试/Java并发.md","headers":[],"bulletin":true}`),a={name:`Java并发.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<p>[TOC]</p><h2 id="线程同步" tabindex="-1"><a class="header-anchor" href="#线程同步"><span>线程同步</span></a></h2><p><a href="https://www.mianshiya.com/bank/1789249312885223425/question/1800347821641375745" target="_blank" rel="noopener noreferrer">什么是 Java 中的线程同步？ - Java 并发面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p>在多线程环境下，避免多个线程对共享资源进行同时访问，引发数据不一致或其它问题的机制。通过同一时刻只有一个线程能够访问共享资源</p><h2 id="线程安全" tabindex="-1"><a class="header-anchor" href="#线程安全"><span>线程安全</span></a></h2><p><a href="https://www.mianshiya.com/bank/1789249312885223425/question/1780933294850863106" target="_blank" rel="noopener noreferrer">Java 中的线程安全是什么意思？ - Java 并发面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p>多个线程访问共享资源时，能保证一致性和正确性</p><h2 id="线程的生命周期在java中如何定义" tabindex="-1"><a class="header-anchor" href="#线程的生命周期在java中如何定义"><span>线程的生命周期在Java中如何定义？</span></a></h2><p><a href="https://www.mianshiya.com/bank/1789249312885223425/question/1780933294871834626" target="_blank" rel="noopener noreferrer">线程的生命周期在 Java 中是如何定义的？ - Java 并发面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><figure><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250106163305676.png" alt="image-20250106163305676" tabindex="0" loading="lazy"><figcaption>image-20250106163305676</figcaption></figure><h2 id="java创建多线程" tabindex="-1"><a class="header-anchor" href="#java创建多线程"><span>Java创建多线程</span></a></h2><p><a href="https://www.mianshiya.com/bank/1789249312885223425/question/1828722732530307073" target="_blank" rel="noopener noreferrer">Java 中如何创建多线程？ - Java 并发面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><h2 id="java线程池原理" tabindex="-1"><a class="header-anchor" href="#java线程池原理"><span>Java线程池原理</span></a></h2><p><a href="https://www.mianshiya.com/bank/1789249312885223425/question/1780933294892806145#heading-0" target="_blank" rel="noopener noreferrer">你了解 Java 线程池的原理吗？ - Java 并发面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p><a href="https://www.mianshiya.com/bank/1789249312885223425/question/1830885090747584514#heading-0" target="_blank" rel="noopener noreferrer">Java 线程池核心线程数在运行过程中能修改吗？如何修改？ - Java 并发面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p>关键参数：</p><h3 id="核心线程数" tabindex="-1"><a class="header-anchor" href="#核心线程数"><span>核心线程数</span></a></h3><p>可以动态修改</p><p><code>ThreadPoolExecutor.setCorePoolSize(int corePoolSize)</code>，修改核心线程数不会中断现有任务，新任务会生效；如果当前线程池中的数量超过核心线程数，多余的线程会在空闲时被回收</p><h3 id="最大线程数" tabindex="-1"><a class="header-anchor" href="#最大线程数"><span>最大线程数</span></a></h3><p>可以动态修改</p><p><code>setMaximumPoolSize(int maximumPoolSize)</code></p><h3 id="空闲存活时间" tabindex="-1"><a class="header-anchor" href="#空闲存活时间"><span>空闲存活时间</span></a></h3><p>超过时间的非核心线程会被销毁</p><h3 id="工作队列" tabindex="-1"><a class="header-anchor" href="#工作队列"><span>工作队列</span></a></h3><ul><li>LinkedBlockingQueue：链表结构的阻塞队列，大小无限</li><li>SynchronousQueue：不存储任务，直接将任务提交给线程</li><li>ArrayBlockingQueue：数组结构的有界阻塞队列</li><li>PriorityBlockingQueue：带优先级的无界阻塞队列</li></ul><h3 id="线程工厂" tabindex="-1"><a class="header-anchor" href="#线程工厂"><span>线程工厂</span></a></h3><h3 id="任务拒绝处理器" tabindex="-1"><a class="header-anchor" href="#任务拒绝处理器"><span>任务拒绝处理器</span></a></h3><ul><li>AbortPolicy：当任务队列满且没有线程空闲，直接抛出异常，默认的拒绝策略。适合需要通知执行失败</li><li>CallerRunsPolicy：当任务队列满且没有线程空闲，由调用者线程执行。适合通过减缓任务提交来稳定系统</li><li>DiscardOldestPolicy：当任务队列满且没有线程空闲，会删除最早的任务，重新提交当前任务。适合丢弃最旧的任务以保证新的重要任务能够被处理</li><li>DiscardPolicy：直接丢弃当前提交的任务，不会执行任何操作，也不会抛出异常。适合对部分任务丢弃没有影响</li><li>自定义拒绝策略，实现RejectedExecutionHandler接口，重写rejectedExecution</li></ul><h3 id="工作原理" tabindex="-1"><a class="header-anchor" href="#工作原理"><span>工作原理</span></a></h3><p>任务提交，线程池线程数未达到核心线程数</p><figure><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250106164353882.png" alt="image-20250106164353882" tabindex="0" loading="lazy"><figcaption>image-20250106164353882</figcaption></figure><p>核心线程数已满，任务队列未满</p><figure><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250106164423270.png" alt="image-20250106164423270" tabindex="0" loading="lazy"><figcaption>image-20250106164423270</figcaption></figure><p>核心线程数已满，任务队列已满</p><figure><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250106164449502.png" alt="image-20250106164449502" tabindex="0" loading="lazy"><figcaption>image-20250106164449502</figcaption></figure><p>线程池中线程数已达最大线程数</p><figure><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250106164530788.png" alt="image-20250106164530788" tabindex="0" loading="lazy"><figcaption>image-20250106164530788</figcaption></figure><h2 id="线程池的实现" tabindex="-1"><a class="header-anchor" href="#线程池的实现"><span>线程池的实现？</span></a></h2><p><a href="https://www.mianshiya.com/bank/1789249312885223425/question/1780933294913777665" target="_blank" rel="noopener noreferrer">Java 并发库中提供了哪些线程池实现？它们有什么区别？ - Java 并发面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><h3 id="fixedthreadpool" tabindex="-1"><a class="header-anchor" href="#fixedthreadpool"><span>FixedThreadPool</span></a></h3><p>创建一个固定数量的线程池</p><p>空闲的线程会被复用，如果没有空闲的线程，新任务会放入队列等待</p><p>适合：负载稳定，任务数量确定且不需要动态调整线程数</p><h3 id="cachethreadpool" tabindex="-1"><a class="header-anchor" href="#cachethreadpool"><span>CacheThreadPool</span></a></h3><p>可根据需要创建新线程的线程池</p><p>线程池线程数量无上限，空闲线程会在60s后被回收，如果由新任务且没有可用线程，会创建新线程</p><p>适合：短期大量并发任务的场景，任务执行时间短且线程数量需求变化较大</p><h3 id="singethreadexecutor" tabindex="-1"><a class="header-anchor" href="#singethreadexecutor"><span>SingeThreadExecutor</span></a></h3><p>创建一个只有单个线程的线程池</p><p>只有一个线程处理任务，任务会按照提交顺序依次执行</p><p>适合：需要保证任务按顺序执行，或不需要并发处理任务</p><h3 id="scheduledthreadpool" tabindex="-1"><a class="header-anchor" href="#scheduledthreadpool"><span>ScheduledThreadPool</span></a></h3><p>支持定时任务和周期性任务的线程池</p><p>可定时或以固定频率执行任务，线程池大小可自定义</p><p>适合：需要周期性执行任务</p><h3 id="workstealingpool" tabindex="-1"><a class="header-anchor" href="#workstealingpool"><span>WorkStealingPool</span></a></h3><p>基于任务窃取算法的线程池</p><p>线程池中每个线程维护一个双端队列，线程可从自己的队列中取任务执行，如果线程的队列为空，可从其他线程的队列中获取任务来执行</p><p>适合：大量小任务并行执行</p><h2 id="使用过哪些并发工具类" tabindex="-1"><a class="header-anchor" href="#使用过哪些并发工具类"><span>使用过哪些并发工具类？</span></a></h2><p><a href="https://www.mianshiya.com/bank/1789249312885223425/question/1780933294930554882" target="_blank" rel="noopener noreferrer">你使用过哪些 Java 并发工具类？ - Java 并发面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><h3 id="concurrenthashmap" tabindex="-1"><a class="header-anchor" href="#concurrenthashmap"><span>concurrenthashmap</span></a></h3><p>线程安全高效的hash表，支持并发访问</p><h3 id="atomicinteger" tabindex="-1"><a class="header-anchor" href="#atomicinteger"><span>atomicinteger</span></a></h3><p>对int类型的原子操作</p><h3 id="countdownlatch" tabindex="-1"><a class="header-anchor" href="#countdownlatch"><span>countdownlatch</span></a></h3><p>一个或多个线程等待其它线程完成操作。通过计数器，当一个线程执行完成后，计数器递减，减到0时，所有等待线程会被唤醒并继续执行</p><h3 id="completablefuture" tabindex="-1"><a class="header-anchor" href="#completablefuture"><span>completablefuture</span></a></h3><p>允许非阻塞地处理异步任务，通过链式调用组合多个异步操作</p><figure><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250107114105286.png" alt="image-20250107114105286" tabindex="0" loading="lazy"><figcaption>image-20250107114105286</figcaption></figure><h2 id="reentrantlock的实现原理" tabindex="-1"><a class="header-anchor" href="#reentrantlock的实现原理"><span>ReentrantLock的实现原理？</span></a></h2><p><a href="https://www.mianshiya.com/bank/1789249312885223425/question/1780933295014440961" target="_blank" rel="noopener noreferrer">Java 中 ReentrantLock 的实现原理是什么？ - Java 并发面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p>基于AQS（抽象、封装；将排队、入队、加锁、中断提供出来）实现的一个可重入锁，支持公平和非公平方式</p><p>内部通过state变量和同步队列、等待队列实现</p><p>利用CAS修改state来争抢锁</p><p>抢不到进入同步队列等待，条件condition不满足进入等待队列</p><p>是否公平锁的区别：线程获取锁时是加入同步队列尾部还是直接利用CAS争抢锁</p><figure><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250107115727555.png" alt="image-20250107115727555" tabindex="0" loading="lazy"><figcaption>image-20250107115727555</figcaption></figure><h2 id="synchronized是怎么实现的" tabindex="-1"><a class="header-anchor" href="#synchronized是怎么实现的"><span>synchronized是怎么实现的？</span></a></h2><p><a href="https://www.mianshiya.com/bank/1789249312885223425/question/1780933294980886530" target="_blank" rel="noopener noreferrer">Java 的 synchronized 是怎么实现的？ - Java 并发面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><figure><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250107122402198.png" alt="image-20250107122402198" tabindex="0" loading="lazy"><figcaption>image-20250107122402198</figcaption></figure><h2 id="synchronized-和-reentrantlock-有什么区别" tabindex="-1"><a class="header-anchor" href="#synchronized-和-reentrantlock-有什么区别"><span>Synchronized 和 ReentrantLock 有什么区别？</span></a></h2><p><a href="https://www.mianshiya.com/bank/1789249312885223425/question/1780933294976692225" target="_blank" rel="noopener noreferrer">Synchronized 和 ReentrantLock 有什么区别？ - Java 并发面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><h2 id="volatile关键字的作用" tabindex="-1"><a class="header-anchor" href="#volatile关键字的作用"><span>volatile关键字的作用</span></a></h2><p><a href="https://www.mianshiya.com/bank/1789249312885223425/question/1780933295115104258" target="_blank" rel="noopener noreferrer">Java 中 volatile 关键字的作用是什么？ - Java 并发面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p><a href="https://www.mianshiya.com/bank/1789249312885223425/question/1780933295043801090" target="_blank" rel="noopener noreferrer">什么是 Java 中的指令重排？ - Java 并发面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p>指令重排：保证单线程程序语义不变的情况下，对指令执行顺序进行调整，以提升执行效率</p><p>volatile：保证变量的可见性和禁止指令重排优化</p><h3 id="可见性" tabindex="-1"><a class="header-anchor" href="#可见性"><span>可见性</span></a></h3><p>当一个线程修改了volatile变量的值，新值会立即被刷新到主内存中，其它线程在读取该变量时可立即获取最新的值。</p><h3 id="禁止指令重排序" tabindex="-1"><a class="header-anchor" href="#禁止指令重排序"><span>禁止指令重排序</span></a></h3><p>通过内存屏障来禁止特定情况下的指令重排序，保证程序执行顺序符合预期。对volatile变量的写操作会在其前面插入一个StoreStore屏障，而对volatile变量的读操作会在其后插入一个LoadLoad屏障。</p>`,93)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};